const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const ctx = body.context || {};
const DEFAULT_BASE = { gemini: 'https://generativelanguage.googleapis.com/v1beta/openai', glm: 'https://api.z.ai/api/paas/v4', openai: 'https://api.openai.com/v1', deepseek: 'https://api.deepseek.com', qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1', kimi: 'https://api.moonshot.cn/v1' };
const DEFAULT_MODEL = { gemini: 'gemini-2.5-flash', glm: 'glm-4.6', openai: 'gpt-4o-mini', deepseek: 'deepseek-chat', qwen: 'qwen-plus', kimi: 'moonshot-v1-8k' };
const CONTENT_TYPES = ['post','story','reels','reuniao','gravacao','evento'];
const CONTENT_STATUSES = ['planejado','producao','revisao','aprovada','standby','publicado'];
const CONTENT_PRIORITIES = ['alta','media','baixa'];
const provider = String(ai.provider || 'gemini').toLowerCase();
const apiKey = String(ai.apiKey || '');
const PREFIX = { gemini: 'gemini', glm: 'glm' };
let model = ai.model || DEFAULT_MODEL[provider] || 'gemini-2.5-flash';
if (PREFIX[provider] && !String(model).toLowerCase().startsWith(PREFIX[provider])) model = DEFAULT_MODEL[provider] || model;
const baseUrl = String(ai.baseUrl || DEFAULT_BASE[provider] || '').replace(/\/+$/, '');
let temperature = Number(ai.temperature);
if (isNaN(temperature)) temperature = 0.7;
temperature = Math.max(0, Math.min(1, temperature));
const NL = String.fromCharCode(10);
const defaultSystem = ['Voce e o assistente do calendario de conteudo de uma agencia brasileira.', 'Responda em pt-BR, de forma direta, usando somente os dados reais do contexto.', 'Nao invente eventos, tasks, clientes, IDs, datas ou midias. Quando faltar um dado, diga objetivamente.'].join(NL);
let system = String(ai.systemPrompt || '').trim() || defaultSystem;
system += NL + NL + 'As regras e dados a seguir COMPLEMENTAM as instrucoes acima (que definem sua persona e tom - em conflito de tom/persona, as instrucoes acima prevalecem).' + NL;
system += '=== CONTEXTO AUTORITATIVO DO CALENDARIO ===' + NL;
system += 'Mes em foco: ' + (ctx.month || '(mes corrente)') + NL;
if (ctx.client) system += 'Cliente em foco: ' + JSON.stringify(ctx.client) + NL;
if (ctx.client && ctx.client.profile) {
  const pr = ctx.client.profile; const ex = pr.extra || {};
  const lbl = { segment: 'segmento', positioning: 'posicionamento', description: 'descricao', history: 'historia', siteUrl: 'site', instagram: 'instagram', address: 'endereco', objectives: 'objetivos', brandVoice: 'tom de voz', audience: 'publico-alvo', offer: 'oferta', pillars: 'pilares', cadence: 'cadencia', restrictions: 'restricoes', performance: 'performance', assets: 'assets' };
  const val = { segment: pr.segment, positioning: pr.positioning, description: pr.description, history: pr.history, siteUrl: pr.siteUrl, instagram: pr.instagram, address: pr.address, objectives: pr.objectives, brandVoice: pr.brandVoice, audience: ex.audience, offer: ex.offer, pillars: ex.pillars, cadence: ex.cadence, restrictions: ex.restrictions, performance: ex.performance, assets: ex.assets };
  const miss = Object.keys(val).filter((k) => !String(val[k] == null ? '' : val[k]).trim()).map((k) => lbl[k]);
  if (miss.length) system += 'Campos do perfil ainda VAZIOS (peca e insista com moderacao): ' + miss.join(', ') + NL;
}
if (Array.isArray(ctx.clients)) system += 'Clientes visiveis: ' + JSON.stringify(ctx.clients) + NL;
system += 'Taxonomia valida: type=' + JSON.stringify(CONTENT_TYPES) + '; status=' + JSON.stringify(CONTENT_STATUSES) + '; priority=' + JSON.stringify(CONTENT_PRIORITIES) + NL;
system += 'Feriados: ' + JSON.stringify(Array.isArray(ctx.holidays) ? ctx.holidays : []) + NL;
system += 'Nota do mes: ' + String(ctx.monthNotes || '') + NL;
system += 'Eventos reais do mes (incluem id, taskId quando vinculado, data, horario, cliente, status, prioridade, responsaveis, descricao e midias):' + NL;
for (const event of (Array.isArray(ctx.events) ? ctx.events : [])) system += '- ' + JSON.stringify(event) + NL;
system += 'Tasks reais do board configurado (incluem id, boardId, coluna, cliente, status, prioridade, responsavel, descricao e datas):' + NL;
for (const task of (Array.isArray(ctx.tasks) ? ctx.tasks : [])) system += '- ' + JSON.stringify(task) + NL;
system += 'Pessoas da equipe (responsaveis/envolvidos possiveis, cada uma com id e name): ' + JSON.stringify(Array.isArray(ctx.people) ? ctx.people : []) + NL;
if (Array.isArray(ctx.plans)) system += 'Planos existentes: ' + JSON.stringify(ctx.plans) + NL;
system += NL + 'INSTRUCAO FINAL: devolva somente um objeto JSON plano, sem markdown, neste formato:' + NL;
system += '{"answer":"resposta em pt-BR","proposals":[],"eventIds":[]}' + NL;
system += '- Ao responder sobre um dia ou periodo, use answer apenas para um resumo curto (total, periodo e observacoes como feriados). NAO liste item a item no texto quando eventIds tiver itens; os cards exibem a lista completa. Coloque em eventIds os IDs de TODOS os eventos correspondentes.' + NL;
system += '- eventIds aceita somente IDs presentes em context.events. Se houver midia, diga que ela aparece nos cards; nao copie URLs no texto.' + NL;
system += '- proposals e a LISTA de itens a criar/editar/excluir; vazio [] = nenhuma acao. UM item por evento/tarefa. No maximo 31 itens; se pedirem mais, gere os 31 primeiros e avise no answer para pedir o restante.' + NL;
system += '- Cada item de proposals tem action (create|update|delete), kind (event|task|note|clientProfile) e fields. EVENTO/TASK usam fields diretos: targetId, title, date, time, type, status, priority, responsibleId, involvedIds, description, contentHtml, dueDate, startDate, dueEndDate, columnId, clientId, clientName, archived. ANOTACAO usa fields.note; PERFIL usa fields.profile + fields.clientId.' + NL;
system += '- EVENTO create/update usa: title, date, time, type, status, priority, responsibleId, involvedIds, description, clientId. Valores de type/status/priority devem vir da taxonomia valida acima. Em update, targetId = id de context.events e envie SOMENTE campos que mudam; title e opcional se a mudanca for prioridade/descricao/status/etc.' + NL;
system += '- TASK create usa: title, description/contentHtml, status, priority, dueDate, time (hora exata HH:MM, junto do dueDate), dueEndDate, type, responsibleId, involvedIds, clientId. TASK update/delete: fields.targetId TEM que ser o UUID do campo id de context.tasks (ou o taskId de context.events) - NUNCA o NOME/titulo da task, NUNCA um id lembrado de mensagens anteriores. Quando o usuario citar a task pelo nome, PROCURE-a em context.tasks pelo title e use o id (UUID) dela. Se nao achar a task no contexto, pergunte no answer em vez de inventar.' + NL;
system += '- TASK MULTI-DIA: quando a task COMECA num dia e TERMINA noutro (ex.: comeca 21/07 e termina 24/07), preencha startDate = dia de INICIO e dueEndDate = dia de FIM (YYYY-MM-DD). NAO ponha o dia final em dueDate; dueDate e so para prazo de dia unico. A barra atravessa os dias no calendario.' + NL;
system += '- TASKS SEM DATA: task de context.tasks com dueDate vazio = task SEM data. Quando pedirem as tasks sem data (ou o que falta agendar), liste exatamente essas. Para dar data/hora a uma delas, gere update com dueDate (e time se houver hora).' + NL;
system += '- CLIENTE: nunca invente clientId. Use clientId do contexto/cliente selecionado quando houver. Se estiver em todos os clientes e nao souber o cliente de uma criacao, deixe clientId vazio para o usuario escolher no card.' + NL;
system += '- RESPONSAVEL/ENVOLVIDOS: o usuario cita pessoas por NOME (ex.: responsavel vai ser a Iasmin). Procure o nome em Pessoas da equipe (ignore acentos/maiusculas; nome parcial vale) e use o ID correspondente em responsibleId/involvedIds. Se o nome nao estiver na lista, coloque o proprio NOME no campo (o sistema resolve ao aplicar). NUNCA exija ID do usuario nem fale em ID com ele - IDs sao internos do sistema. So pergunte se DUAS pessoas da lista empatarem no nome.' + NL;
if (body.viaVoice === true) system += 'ESTA MENSAGEM VEIO DE TRANSCRICAO DE AUDIO: erros foneticos sao PROVAVEIS (ex.: rios ~ reels, historia ~ story). Interprete pelo contexto do dominio ANTES de dizer que nao entendeu ou nao achou; corrija e avise, ou pergunte na duvida.' + NL;
system += '- INTELIGENCIA DE DOMINIO: voce vive no mundo de marketing de conteudo (Instagram, postagens, reels, stories, campanhas, gravacoes). Palavra que NAO existe nesse mundo e provavelmente erro de transcricao de audio ou typo - corrija pelo termo mais proximo do dominio E AVISE no answer (ex.: rios => entendi reels). Se houver mais de uma interpretacao plausivel, pergunte: voce quis dizer X ou Y? NUNCA use um type fora da taxonomia valida.' + NL;
system += '- TITULO COM ERRO: titulos citados podem vir com typos ou erros de fala (multi dia testi). Compare por SIMILARIDADE com os titulos REAIS de context.events e context.tasks: 1 candidato proximo => use-o e siga com a proposta (o cartao confirma); diferenca grande ou varios candidatos => pergunte: voce quis dizer {titulo}? NUNCA responda que nao achou sem antes tentar a similaridade.' + NL;
system += '- CONSULTORIA: alem do CRUD, voce e ESTRATEGISTA de conteudo. Quando pedirem ideias, dicas ou estrategias (campanhas, reels, copys, carrosseis, calendario editorial), responda com sugestoes CONCRETAS usando o PERFIL do cliente do contexto (segmento, tom de voz, objetivos, pilares). Sugestao aceita pode virar proposta de criacao.' + NL;
system += '- PRIORIDADE DO CALENDARIO: quando o usuario pedir para editar/excluir "a tarefa/item do dia X" (ou de um cliente), procure PRIMEIRO em context.events (o CALENDARIO). Use o id de um evento cuja data (campo date) seja EXATAMENTE o dia pedido. NAO escolha um item de outro dia nem um id lembrado de antes. Se houver VARIOS eventos no dia, liste-os no answer e pergunte qual - NAO gere proposta chutando um. Se NAO houver evento no calendario naquele dia, mas existir uma task correspondente em context.tasks (sem evento), NAO gere a proposta: avise no answer que o item nao esta no calendario, que voce achou em Tasks, e pergunte se pode alterar la. NUNCA altere um item fora do calendario sem essa confirmacao explicita.' + NL;
system += '- ALVO POR NOME: quando o usuario citar o item pelo titulo (ex.: o reel de dona evania), ache-o em context.events ou context.tasks pelo titulo (parcial vale, sem acento) e use o id real em targetId. Com 1 candidato claro, GERE a proposta direto - o cartao de confirmacao ja mostra o item com titulo e mudancas; nao pergunte de novo no texto.' + NL;
system += '- O CARTAO E A CONFIRMACAO: NUNCA peca confirmacao por texto antes de propor (nada de confirme se deseja...). Se a intencao de criar/editar/excluir esta clara, SEMPRE emita a proposta com o valor final ja calculado - o usuario revisa e confirma NO CARTAO. DATA RELATIVA (adia 2 dias, antecipa 1 semana, joga pra sexta): calcule a partir da data ATUAL do item no contexto e proponha a data resultante (ex.: item em 25/07 + adia 2 dias => dueDate 27/07).' + NL;
system += '- UPDATE MINIMO: na proposta de update inclua APENAS os campos que o usuario pediu para mudar (alem de targetId/targetKind). NUNCA reenvie campos que nao mudaram (prioridade, tipo, datas, responsavel, cliente...) - reenviar um campo altera o item sem o usuario pedir.' + NL;
system += '- CRUD: create = item novo. update = editar item EXISTENTE. delete = excluir. Use update/delete SO com targetId real de context.events ou context.tasks; se nao achar alvo, nao gere proposal e pergunte no answer.' + NL;
system += '- MES DA ANOTACAO: a anotacao (kind:note) e do MES EM FOCO (context.month), SEMPRE - mesmo que o CONTEUDO do texto cite outro mes (ex.: anotar Planejamento agosto em julho => month = mes em foco). So use outro month se o usuario disser explicitamente que a anotacao e DE outro mes.' + NL;
system += '- ANOTACAO DO MES (kind:note) = o QUADRO de ANOTACOES da ESQUERDA da tela (calendar.notes): um texto livre por mes (foco, pautas, ideias, lembretes). NAO e Tarefa/Evento nem Perfil do cliente. Gatilhos: anotar, anota, anotacao do mes, nota do mes, escreve na anotacao, poe no quadro de anotacoes. SEMPRE que o usuario pedir para ANOTAR/escrever algo do mes, use kind:note (NUNCA event/task/clientProfile) e coloque o texto em fields.note.content. fields.note = { month(YYYY-MM, vazio=mes em foco), content(o texto a anotar), mode(append|replace) }: append por PADRAO (acrescenta ao que existe), replace SO se pedirem para reescrever, action delete limpa a nota do mes.' + NL;
system += '- PERFIL DO CLIENTE (kind:clientProfile): preenche/edita a inteligencia de UM cliente ja existente. fields.clientId = o id REAL do cliente (procure o NOME citado em context.clients OU context.client - cada um tem id e name - e use o id) e fields.clientName = o nome; SEMPRE preencha os DOIS quando o cliente for nomeado. Editar perfil NAO troca o cliente (o cliente e a IDENTIDADE do perfil). Se o usuario NAO disse o cliente e nao da pra inferir, NAO emita a proposta: pergunte no answer qual cliente. fields.profile = { segment, positioning, description, history, siteUrl, instagram, address, objectives, brandVoice, extra{audience,offer,pillars,cadence,restrictions,performance,assets}, clearFields[], clearAll }. Preencha SO os campos que o usuario informou (o resto e preservado). delete: clearFields[campo] apaga um campo; clearAll true zera o perfil. Numa edicao DIRETA (o usuario ja deu o valor, ex.: a descricao), so monte a proposta com aquele campo; pode citar DE LEVE o que ainda falta, sem virar uma lista de perguntas. NAO confunda o PERFIL com a ANOTACAO do mes: dado estruturado do cliente vai no PERFIL (aba Clientes); texto solto do mes vai na ANOTACAO (note, quadro da esquerda).' + NL;
system += '- INSISTENCIA no perfil: quando descreverem um cliente (voz ou texto), extraia o maximo de campos e gere UMA proposta clientProfile; no answer liste os campos ainda VAZIOS (use a linha Campos do perfil ainda VAZIOS no escopo cliente, ou o profileMissing de cada cliente no escopo todos) e peca-os de forma objetiva. Se ignorarem, repergunte UMA vez mais, com moderacao.' + NL;
system += '- PERGUNTA campo-a-campo: qual o segmento/historia/objetivo do cliente X responde do perfil do contexto (escopo cliente traz o perfil completo). No escopo todos, se faltar o detalhe, responda o que tiver e sugira focar o cliente.' + NL;
system += '- Seja PROATIVO: quando pedirem para criar/editar/excluir e o alvo estiver claro, gere as propostas em vez de so responder texto.' + NL;
system += '- Quando houver proposals, o answer e CURTO (1 frase), NAO repete a lista e NUNCA diz que a acao foi feita (nada foi aplicado ainda - o usuario ainda vai aprovar no cartao). Ex.: Preparei a proposta abaixo, e so revisar e confirmar.' + NL;
system += '- HORARIO: preencha time SO com hora exata (ex.: 14:00, 09:30). Periodo vago (manha/tarde/noite) ou so o dia => time VAZIO; NAO converta manha em 09:00. So peca confirmacao se for realmente impossivel decidir a data.';
system += NL + 'REGRA DE OURO (vale acima de tudo): voce NUNCA executa, aplica, salva nem grava nada por conta propria. TODA criacao ou alteracao (evento, task, anotacao, perfil do cliente) SO acontece DEPOIS que o usuario aprova o CARTAO da proposta. Portanto: (1) sempre que pedirem para criar/adicionar/mudar/preencher/apagar algo, isso TEM que ir em proposals[] - se voce nao colocar, NADA acontece; (2) NUNCA escreva que fez/adicionou/criou/editou/salvou/atualizou/pronto/feito - isso seria MENTIRA, porque nada foi aplicado; fale sempre no futuro, ex.: Preparei a proposta abaixo, e so revisar e confirmar; (3) se faltar informacao para montar a proposta, PERGUNTE - nunca finja que fez.';
const history = [];
for (const h of (Array.isArray(body.history) ? body.history : [])) {
  const role = String((h && h.role) || '');
  const content = String((h && h.content) || '');
  if ((role === 'user' || role === 'assistant') && content) history.push({ role, content });
}
const messages = [{ role: 'system', content: system }, ...history, { role: 'user', content: String(body.question || '').trim() }];
return [{ json: { provider, model, baseUrl, apiKey, temperature, messages } }];

let r = $input.first().json || {};
if (Array.isArray(r)) r = r[0] || {};
if (r.error) {
  const raw = String((r.error && (r.error.message || r.error.description)) || '');
  const low = raw.toLowerCase();
  let answer = 'Nao consegui falar com a IA agora. Tente de novo.';
  if (low.includes('503') || low.includes('unavailable') || low.includes('overload')) answer = 'O provedor de IA esta sobrecarregado agora. Tente de novo em instantes.';
  else if (low.includes('429') || low.includes('quota') || low.includes('rate')) answer = 'Limite de uso do provedor de IA atingido. Tente mais tarde ou troque de modelo.';
  else if (low.includes('401') || low.includes('403') || low.includes('api key')) answer = 'A chave de API do provedor foi recusada. Confira a chave na aba IA.';
  return [{ json: { answer, eventIds: [], aiError: true } }];
}
const choices = Array.isArray(r.choices) ? r.choices : [];
const msg = (choices[0] && choices[0].message && choices[0].message.content) || '';
if (!msg) return [{ json: { answer: 'A IA respondeu vazio. Verifique o modelo configurado.', eventIds: [], aiError: true } }];
let text = String(msg).trim();
const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1].trim();
const a = text.indexOf('{'), b = text.lastIndexOf('}');
let env = null;
try { if (a >= 0 && b > a) env = JSON.parse(text.slice(a, b + 1)); } catch (_) {}
if (!env || typeof env !== 'object') return [{ json: { answer: String(msg), eventIds: [] } }];
const answer = String(env.answer == null ? '' : env.answer) || String(msg);
const eventIds = Array.isArray(env.eventIds) ? env.eventIds.map(String) : [];
let srcList = Array.isArray(env.proposals) ? env.proposals : [];
const legacy = String(env.create || 'none').toLowerCase();
if (!srcList.length && (legacy === 'event' || legacy === 'task')) srcList = [{ kind: legacy, fields: env }];
function has(obj, key) { return !!obj && Object.prototype.hasOwnProperty.call(obj, key); }
function firstText(src, keys) {
  for (const key of keys) {
    if (!has(src, key)) continue;
    const value = String(src[key] == null ? '' : src[key]).trim();
    if (value) return value;
  }
  return '';
}
function setText(fields, outKey, src, keys) {
  const value = firstText(src, keys || [outKey]);
  if (value) fields[outKey] = value;
}
function setArray(fields, outKey, src, keys) {
  for (const key of keys || [outKey]) {
    if (!has(src, key)) continue;
    const raw = src[key];
    const value = Array.isArray(raw) ? raw.map((item) => String(item || '').trim()).filter(Boolean) : [];
    if (value.length) fields[outKey] = Array.from(new Set(value));
    return;
  }
}
function setBool(fields, outKey, src, keys) {
  for (const key of keys || [outKey]) {
    if (!has(src, key)) continue;
    if (typeof src[key] === 'boolean') fields[outKey] = src[key];
    return;
  }
}
function hasEditable(fields) {
  return Object.keys(fields).some((key) => key !== 'targetId');
}
function canonicalKind(raw) {
  const k = String(raw || '').toLowerCase().trim();
  if (k === 'event' || k === 'task' || k === 'note') return k;
  if (k === 'clientprofile' || k === 'client_profile' || k === 'profile') return 'clientProfile';
  return '';
}
const PROFILE_KEYS = ['segment', 'positioning', 'description', 'history', 'siteUrl', 'instagram', 'address', 'objectives', 'brandVoice'];
const EXTRA_KEYS = ['audience', 'offer', 'pillars', 'cadence', 'restrictions', 'performance', 'assets'];
const CLEARABLE = PROFILE_KEYS.concat(EXTRA_KEYS);
const PROFILE_ALIASES = { segment: ['segment', 'segmento'], positioning: ['positioning', 'posicionamento'], description: ['description', 'descricao'], history: ['history', 'historia'], siteUrl: ['siteUrl', 'site', 'website'], instagram: ['instagram', 'ig'], address: ['address', 'endereco'], objectives: ['objectives', 'objetivos'], brandVoice: ['brandVoice', 'tomDeVoz', 'voice'] };
const proposals = [];
for (const p of srcList) {
  const kind = canonicalKind(p && p.kind);
  if (!kind) continue;
  let action = String((p && p.action) || 'create').toLowerCase();
  if (action !== 'create' && action !== 'update' && action !== 'delete') action = 'create';
  const src = (p && p.fields && typeof p.fields === 'object') ? p.fields : (p || {});
  if (kind === 'note') {
    const sn = (src.note && typeof src.note === 'object') ? src.note : src;
    const note = {};
    setText(note, 'month', sn, ['month', 'mes']);
    setText(note, 'content', sn, ['content', 'conteudo', 'text', 'texto']);
    const nmode = String((sn && sn.mode) || '').toLowerCase().trim();
    if (nmode === 'append' || nmode === 'replace') note.mode = nmode;
    if (action !== 'delete' && !note.content) continue;
    proposals.push({ action, kind, fields: { note } });
    if (proposals.length >= 31) break;
    continue;
  }
  if (kind === 'clientProfile') {
    const sp = (src.profile && typeof src.profile === 'object') ? src.profile : src;
    const profile = {};
    for (const pk of PROFILE_KEYS) setText(profile, pk, sp, PROFILE_ALIASES[pk]);
    const rawExtra = (sp && sp.extra && typeof sp.extra === 'object') ? sp.extra : sp;
    const extra = {};
    for (const ek of EXTRA_KEYS) setText(extra, ek, rawExtra, [ek]);
    if (Object.keys(extra).length) profile.extra = extra;
    if (Array.isArray(sp && sp.clearFields)) {
      const cf = sp.clearFields.map((x) => String(x || '').trim()).filter((x) => CLEARABLE.indexOf(x) >= 0);
      if (cf.length) profile.clearFields = Array.from(new Set(cf));
    }
    if ((sp && sp.clearAll) === true) profile.clearAll = true;
    const pfields = { profile };
    setText(pfields, 'clientId', src, ['clientId', 'clientAccountId']);
    if (!has(pfields, 'clientId')) setText(pfields, 'clientId', sp, ['clientId', 'clientAccountId']);
    setText(pfields, 'clientName', src, ['clientName', 'client', 'cliente']);
    if (!has(pfields, 'clientName')) setText(pfields, 'clientName', sp, ['clientName', 'client', 'cliente']);
    const hasField = PROFILE_KEYS.some((pk) => has(profile, pk)) || !!(profile.extra && Object.keys(profile.extra).length);
    if (action === 'delete') { if (!profile.clearAll && !(profile.clearFields && profile.clearFields.length)) continue; }
    else if (!hasField) continue;
    proposals.push({ action, kind, fields: pfields });
    if (proposals.length >= 31) break;
    continue;
  }
  const fields = {};
  setText(fields, 'targetId', src, ['targetId', 'eventId', 'taskId', 'id']);
  setText(fields, 'title', src, ['title', 'titulo', 'name']);
  setText(fields, 'date', src, ['date', 'data']);
  setText(fields, 'time', src, ['time', 'hora', 'horario']);
  setText(fields, 'type', src, ['type', 'tipo']);
  setText(fields, 'status', src, ['status']);
  setText(fields, 'priority', src, ['priority', 'prioridade']);
  setText(fields, 'responsibleId', src, ['responsibleId', 'responsibleUserId', 'responsible', 'responsavel', 'responsibleName']);
  setArray(fields, 'involvedIds', src, ['involvedIds', 'involved', 'assignees', 'envolvidos']);
  setText(fields, 'description', src, ['description', 'descricao', 'body', 'copy']);
  setText(fields, 'contentHtml', src, ['contentHtml']);
  setText(fields, 'dueDate', src, ['dueDate', 'date', 'dataEntrega']);
  setText(fields, 'startDate', src, ['startDate']);
  setText(fields, 'dueEndDate', src, ['dueEndDate']);
  setText(fields, 'columnId', src, ['columnId']);
  setText(fields, 'clientId', src, ['clientId', 'clientAccountId']);
  setText(fields, 'clientName', src, ['clientName']);
  setBool(fields, 'archived', src, ['archived', 'arquivada']);
  if (action === 'create' && !fields.title) continue;
  if (action === 'update' && !hasEditable(fields)) continue;
  proposals.push({ action, kind, fields });
  if (proposals.length >= 31) break;
}
return [{ json: { answer, eventIds, proposals } }];
